import { HOUR_MS } from './constants';
import { slerp, type Quat, type V3 } from './vec';

/**
 * Hourly NASA/JPL DE440 geometry generated by scripts/generate_ephemeris.py.
 * Vectors are geometric positions relative to the Moon's centre in the
 * MOON_ME_DE440_ME421 frame (km). Between samples, positions are linearly
 * interpolated (validated against direct SPICE in tests) and orientation
 * quaternions are slerped.
 */
export interface EphemerisMeta {
  version: number;
  frame: string;
  origin: string;
  reference: string;
  units: string;
  aberrationCorrection: string;
  startUtc: string;
  endUtc: string;
  stepSeconds: number;
  count: number;
  stride: number;
  columns: string[];
  sha256: string;
  kernels: { url: string; sha256: string }[];
}

export interface Ephemeris {
  meta: EphemerisMeta;
  start: number;
  end: number;
  step: number;
  count: number;
  stride: number;
  data: Float64Array;
}

const EXPECTED_COLUMNS = 'sunX,sunY,sunZ,earthX,earthY,earthZ,qJ2000X,qJ2000Y,qJ2000Z,qJ2000W,qEarthX,qEarthY,qEarthZ,qEarthW';

export function parseEphemeris(meta: EphemerisMeta, buffer: ArrayBuffer): Ephemeris {
  if (meta.version !== 2 || meta.frame !== 'MOON_ME_DE440_ME421' || meta.units !== 'km' || meta.origin !== 'MOON_CENTER') {
    throw new Error('Unsupported ephemeris metadata.');
  }
  if (meta.columns.join(',') !== EXPECTED_COLUMNS || meta.stride !== 14) {
    throw new Error('Unexpected ephemeris columns.');
  }
  const floats = new Float32Array(buffer);
  if (floats.length !== meta.count * meta.stride) {
    throw new Error(`Ephemeris is truncated: ${floats.length} of ${meta.count * meta.stride} values.`);
  }
  const start = Date.parse(meta.startUtc);
  const end = Date.parse(meta.endUtc);
  const step = meta.stepSeconds * 1000;
  if (step !== HOUR_MS || (end - start) / step + 1 !== meta.count) {
    throw new Error('Ephemeris time axis is inconsistent.');
  }
  const data = Float64Array.from(floats);
  for (let i = 0; i < data.length; i++) {
    if (!Number.isFinite(data[i])) throw new Error('Ephemeris contains non-finite values.');
  }
  return { meta, start, end, step, count: meta.count, stride: meta.stride, data };
}

export async function loadEphemeris(base = import.meta.env.BASE_URL): Promise<Ephemeris> {
  const [metaRes, binRes] = await Promise.all([fetch(`${base}data/ephemeris.json`), fetch(`${base}data/ephemeris.bin`)]);
  if (!metaRes.ok || !binRes.ok) throw new Error('The ephemeris files could not be loaded.');
  return parseEphemeris((await metaRes.json()) as EphemerisMeta, await binRes.arrayBuffer());
}

export const clampTime = (eph: Ephemeris, t: number): number => Math.min(eph.end, Math.max(eph.start, t));
export const inRange = (eph: Ephemeris, t: number): boolean => t >= eph.start && t <= eph.end;

function locate(eph: Ephemeris, t: number): [number, number] {
  const x = (clampTime(eph, t) - eph.start) / eph.step;
  const i = Math.min(eph.count - 2, Math.floor(x));
  return [i, x - i];
}

function lerpColumns(eph: Ephemeris, t: number, col: number, out: V3): V3 {
  const [i, f] = locate(eph, t);
  const a = i * eph.stride + col;
  const b = a + eph.stride;
  const d = eph.data;
  out[0] = d[a] + (d[b] - d[a]) * f;
  out[1] = d[a + 1] + (d[b + 1] - d[a + 1]) * f;
  out[2] = d[a + 2] + (d[b + 2] - d[a + 2]) * f;
  return out;
}

/** Sun position relative to the Moon's centre, Moon-fixed frame, km. */
export const sunAt = (eph: Ephemeris, t: number, out: V3 = [0, 0, 0]): V3 => lerpColumns(eph, t, 0, out);
/** Earth position relative to the Moon's centre, Moon-fixed frame, km. */
export const earthAt = (eph: Ephemeris, t: number, out: V3 = [0, 0, 0]): V3 => lerpColumns(eph, t, 3, out);

function quatColumns(eph: Ephemeris, t: number, col: number, out: Quat): Quat {
  const [i, f] = locate(eph, t);
  const a = i * eph.stride + col;
  const b = a + eph.stride;
  const d = eph.data;
  return slerp([d[a], d[a + 1], d[a + 2], d[a + 3]], [d[b], d[b + 1], d[b + 2], d[b + 3]], f, out);
}

/** Rotation taking J2000 (ICRF) vectors into the Moon-fixed frame. Used for star placement. */
export const skyRotationAt = (eph: Ephemeris, t: number, out: Quat = [0, 0, 0, 1]): Quat => quatColumns(eph, t, 6, out);
/** Rotation taking IAU_EARTH body-fixed vectors into the Moon-fixed frame. Used to orient Earth's surface. */
export const earthRotationAt = (eph: Ephemeris, t: number, out: Quat = [0, 0, 0, 1]): Quat => quatColumns(eph, t, 10, out);
